// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }

    function testFuzz_property(address actor, uint256 val) public {
        vm.assume(actor != address(0));

        vm.deal(actor, 1 wei);

        bool ok;
        vm.prank(actor);
        try c.SetMinSum(val) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
